/// Extended effect library (FotoPlay-class "Efekt" / "Rama" catalogue):
/// texture particle layers, decorative frames, light sprites and beat
/// impact effects. All textures are original artwork generated by
/// `scripts/make_fx_assets.py` and shipped in `assets/fx/`.
///
/// The same definitions drive the FFmpeg renderer (here) and the Flutter
/// live preview (`ui/preview/fx_painters.dart`) so both look alike.
class FxAssets {
  /// Directory holding the extracted `assets/fx/*.png` files. Set by
  /// Services on start-up; defaults to the source tree for tests/tools.
  static String dir = 'assets/fx';
  static String path(String file) => '$dir/$file';
}

/// Particle texture definition. Speeds are in texture-heights (vy, +down)
/// and texture-widths (vx, +right) per second; [sway] adds a slow
/// horizontal oscillation (fraction of width).
class ParticleTex {
  final String file;
  final double vx, vy, sway;
  final double opacity;
  const ParticleTex(this.file, {this.vx = 0, this.vy = 0.05, this.sway = 0, this.opacity = 1});
}

