bool isLibraryVfx(String type) =>
    particleTextures.containsKey(type) || frameTextures.containsKey(type) || spriteEffects.containsKey(type) || impactEffects.contains(type);

/// Default beat grid when no music analysis is available (120 BPM).
List<double> fallbackBeats(double duration, {double period = 0.5}) => [for (var t = 0.0; t < duration; t += period) t];

/// Tiling geometry for a 1080×1920 particle texture covering W×H: the
/// texture is repeated [n] times horizontally and scaled by [k].
(int n, double k, int tw, int th) texTiling(int w, int h) {
  final n = math.max(1, ((w / h) / (1080 / 1920)).round());
  final k = math.max(w / (1080 * n), h / 1920);
  int even(double v) => (v.round() ~/ 2 * 2).clamp(2, 1 << 15);
  return (n, k, even(1080 * n * k), even(1920 * k));
}

/// Applies a library effect; returns the new base label or null when the
/// type is not part of the library.
String? applyLibraryVfx(VfxContext x, String base, VfxItem it) {
  final i = it.intensity.clamp(0.0, 1.0);
  final b = x.b;
  final fps = FfEscape.num(x.fps);
  final s = it.start, e = it.duration > 0 ? it.start + it.duration : x.duration;
  final en = "enable='between(t,${fsec(s)},${fsec(e)})'";
  final beats = x.beats.isNotEmpty ? x.beats : fallbackBeats(x.duration);
  double beatEnv(double t, double decay) {
    var lo = 0, hi = beats.length - 1, idx = -1;
    while (lo <= hi) {
      final m = (lo + hi) >> 1;
      if (beats[m] <= t) {
        idx = m;
        lo = m + 1;
      } else {
        hi = m - 1;
      }
    }
    return idx < 0 ? 0 : math.exp(-(t - beats[idx]) * decay);
  }

  String img(String file) {
    final p = FxAssets.path(file);
    if (!File(p).existsSync()) throw StateError('Brak tekstury efektu: $p');
    return '${b.addInput(p, pre: ['-loop', '1', '-framerate', fps])}:v';
  }

  final pt = particleTextures[it.type];
  if (pt != null) {
    final (n, _, tw, th) = texTiling(x.w, x.h);
    final src = img(pt.file), tex = b.label('tx'), out = b.label('txo');
    final tile = n > 1 ? ',split=$n${[for (var k = 0; k < n; k++) '[${tex}_$k]'].join()};${[for (var k = 0; k < n; k++) '[${tex}_$k]'].join()}hstack=inputs=$n' : '';
    // scroll: +v moves content up; our vy is +down → negate.
    final vxF = -pt.vx / x.fps, vyF = -pt.vy / x.fps; // scroll moves content by (-h,-v) per frame (verified)
    final op = (pt.opacity * (0.45 + 0.55 * i)).clamp(0.0, 1.0);
    final cmd = it.reactive && x.music != null
        ? (() {
            final inst = b.label('tccm');
            return (x.sendcmdFile(inst, (v) => 'colorchannelmixer@$inst aa ${FfEscape.num(op * (0.3 + 0.7 * v))}', env: (t) => math.max(x.beatEnv(t, decay: 4), x.energyAt(t) * 0.7)), inst);
          })()
        : null;
    final ccm = cmd == null ? 'colorchannelmixer=aa=${FfEscape.num(op)}' : 'sendcmd=f=${cmd.$1},colorchannelmixer@${cmd.$2}=aa=${FfEscape.num(op)}';
    b.chains.add('[$src]format=rgba,trim=end_frame=1$tile,scale=$tw:$th,loop=loop=-1:size=1,trim=duration=${fsec(x.duration)},setpts=N/($fps*TB),'
        'scroll=h=${FfEscape.num(vxF)}:v=${FfEscape.num(vyF)},crop=${x.w}:${x.h}:0:0,$ccm[$tex]');
    // Sway: horizontal offset oscillation. The texture is wider than the
    // frame by 2*amp so no empty edge ever shows.
    b.chains.add("[$base][$tex]overlay=x='${(pt.sway * x.w).round()}*sin(t*0.9)':y=0:$en[$out]");
    return out;
  }

  final fr = frameTextures[it.type];
  if (fr != null) {
    final src = img(fr), lay = b.label('frl'), out = b.label('fro');
    b.chains.add('[$src]format=rgba,trim=end_frame=1,scale=${x.w}:${x.h},loop=loop=-1:size=1,trim=duration=${fsec(x.duration)},setpts=N/($fps*TB),colorchannelmixer=aa=${FfEscape.num(0.6 + 0.4 * i)}[$lay]');
    b.chains.add('[$base][$lay]overlay=0:0:$en[$out]');
    return out;
  }

  final sp = spriteEffects[it.type];
  if (sp != null) {
    final m = math.min(x.w, x.h);
    final src = img(sp), lay = b.label('spl'), out = b.label('spo');
    final inst = b.label('sps'), ia = b.label('spa');
    switch (it.type) {
      case 'shockwave':
      case 'lightburst':
        // grows from small to large after each beat and fades out
        final ring = it.type == 'shockwave';
        final base0 = ring ? m * 0.25 : m * 0.6;
        final grow = ring ? m * 1.6 : m * 0.9;
        final cmd = x.sendcmdFile(inst, (v) {
          final ph = 1 - v; // 0 at beat → 1 later
          final sz = (base0 + grow * ph).round() ~/ 2 * 2;
          final a = (v * (0.5 + 0.5 * i)).clamp(0.0, 1.0);
          return 'scale@$inst w $sz, scale@$inst h $sz, colorchannelmixer@$ia aa ${FfEscape.num(a)}';
        }, env: (t) => beatEnv(t, ring ? 3.5 : 5), rate: math.min(x.fps, 30));
        final sz0 = base0.round() ~/ 2 * 2;
        b.chains.add('[$src]format=rgba,trim=end_frame=1,loop=loop=-1:size=1,trim=duration=${fsec(x.duration)},setpts=N/($fps*TB),sendcmd=f=$cmd,scale@$inst=w=$sz0:h=$sz0,colorchannelmixer@$ia=aa=0'
            '${it.color != '#FFFFFF' ? ',colorchannelmixer=rr=${_chan(it.color, 0)}:gg=${_chan(it.color, 1)}:bb=${_chan(it.color, 2)}' : ''}[$lay]');
        b.chains.add("[$base][$lay]overlay=x='(W-w)/2':y='(H-h)/2':eof_action=pass:$en[$out]");
        return out;
      case 'godrays':
        final d = (math.sqrt(x.w * x.w + x.h * x.h)).round() ~/ 2 * 2;
        b.chains.add("[$src]format=rgba,trim=end_frame=1,scale=$d:$d,loop=loop=-1:size=1,trim=duration=${fsec(x.duration)},setpts=N/($fps*TB),rotate=a='t*0.12':c=none:ow=$d:oh=$d,"
            'crop=${x.w}:${x.h}:(iw-${x.w})/2:(ih-${x.h})/2-${(x.h * 0.25).round()},colorchannelmixer=aa=${FfEscape.num(0.5 + 0.5 * i)}[$lay]');
        b.chains.add('[$base][$lay]overlay=0:0:$en[$out]');
        return out;
      case 'speedlines':
        final d = (math.sqrt(x.w * x.w + x.h * x.h) * 1.05).round() ~/ 2 * 2;
        // flicker: random rotation every 3 frames
        b.chains.add("[$src]format=rgba,trim=end_frame=1,scale=$d:$d,loop=loop=-1:size=1,trim=duration=${fsec(x.duration)},setpts=N/($fps*TB),rotate=a='floor(n/3)*2.39996':c=none:ow=$d:oh=$d,"
            'crop=${x.w}:${x.h}:(iw-${x.w})/2:(ih-${x.h})/2,colorchannelmixer=aa=${FfEscape.num(0.55 + 0.45 * i)}[$lay]');
        b.chains.add('[$base][$lay]overlay=0:0:$en[$out]');
        return out;
      case 'halftone':
      case 'aura':
        final d = math.max(x.w, x.h);
        b.chains.add('[$src]format=rgba,trim=end_frame=1,scale=$d:$d,crop=${x.w}:${x.h},loop=loop=-1:size=1,trim=duration=${fsec(x.duration)},setpts=N/($fps*TB),colorchannelmixer=aa=${FfEscape.num(0.5 + 0.5 * i)}'
            '${it.type == 'aura' && it.color != '#FFFFFF' ? ',colorchannelmixer=rr=${_chan(it.color, 0)}:gg=${_chan(it.color, 1)}:bb=${_chan(it.color, 2)}' : ''}[$lay]');
        b.chains.add('[$base][$lay]overlay=0:0:$en[$out]');
        return out;
    }
  }

  switch (it.type) {
    case 'zoompunch':
    case 'heartbeat':
      // scaled copy of the picture laid over itself (centred) on beats
      final hb = it.type == 'heartbeat';
      final amp = (hb ? 0.05 : 0.08) + (hb ? 0.05 : 0.12) * i;
      final a = b.label('zpa'), c = b.label('zpb'), z = b.label('zpz'), out = b.label('zpo');
      final inst = b.label('zps');
      double env(double t) => hb ? _heartbeat(t) : beatEnv(t, 7);
      final cmd = x.sendcmdFile(inst, (v) {
        final k = 1 + amp * v;
        return 'scale@$inst w ${(x.w * k).round() ~/ 2 * 2}, scale@$inst h ${(x.h * k).round() ~/ 2 * 2}';
      }, env: env, rate: math.min(x.fps, 30));
      b.chains.add('[$base]split[$a][$c]');
      b.chains.add('[$c]sendcmd=f=$cmd,scale@$inst=w=${x.w}:h=${x.h}[$z]');
      b.chains.add("[$a][$z]overlay=x='(W-w)/2':y='(H-h)/2':$en[$out]");
      return out;
    case 'shake':
      final pad = (math.min(x.w, x.h) * (0.02 + 0.05 * i)).round() ~/ 2 * 2;
      final inst = b.label('shk');
      final cmd = x.sendcmdFile(inst, (v) => 'crop@$inst x ${(pad + pad * v * 0.9 * math.sin(v * 91)).round()}, crop@$inst y ${(pad + pad * v * 0.9 * math.cos(v * 57)).round()}',
          env: (t) => beatEnv(t, 6) * (0.75 + 0.25 * math.sin(t * 53)).abs(), rate: math.min(x.fps, 30));
      final w2 = x.w + pad * 2, h2 = x.h + pad * 2;
      return _onRange(x, base, s, e, 'scale=$w2:$h2,sendcmd=f=$cmd,crop@$inst=w=${x.w}:h=${x.h}:x=$pad:y=$pad');
    case 'strobe':
      final times = beats;
      final enS = times.take(400).map((t) => 'between(t,${fsec(t)},${fsec(t + 0.04)})').join('+');
      return _onRange(x, base, s, e, "eq=brightness=${FfEscape.num(0.5 + 0.4 * i)}:contrast=0.6:enable='${enS.isEmpty ? '0' : enS}'");
  }
  return null;
}

String _onRange(VfxContext x, String base, double s, double e, String filters) {
  final out = x.b.label('lr');
  if (s <= 0.001 && e >= x.duration - 0.001) {
    x.b.chains.add('[$base]$filters[$out]');
  } else {
    final a = x.b.label('la'), bb = x.b.label('lb'), f = x.b.label('lf');
    x.b.chains.add("[$base]split[$a][$bb];[$bb]$filters[$f];[$a][$f]overlay=enable='between(t,${fsec(s)},${fsec(e)})'[$out]");
  }
  return out;
}

String _chan(String hex, int i) {
  final h = hex.replaceFirst('#', '');
  if (h.length < 6) return '1';
  return FfEscape.num(int.parse(h.substring(i * 2, i * 2 + 2), radix: 16) / 255);
}

/// Double-pulse heartbeat envelope (~72 BPM), 0..1.
double _heartbeat(double t) {
  const period = 60 / 72;
  final ph = t % period;
  double p(double c) => math.exp(-math.pow((ph - c) / 0.045, 2).toDouble());
  return math.max(p(0.05), 0.7 * p(0.27));
}

double heartbeatEnvelope(double t) => _heartbeat(t);

/// Info used by the UI and tests.
Map<String, dynamic> vfxLibraryInfo() => {
      'particles': particleTextures.length,
      'frames': frameTextures.length,
      'sprites': spriteEffects.length,
      'impact': impactEffects.length,
      'categories': vfxCategories.length,
    };
